import type { ProductPerformance } from '@/lib/vendor/analytics'

export function AnalyticsPerformanceTable({ products, title }: { products: ProductPerformance[]; title: string }) { return <section className="analytics-panel"><div className="analytics-panel-heading"><h2>{title}</h2></div>{products.length ? <div className="analytics-performance-wrap"><table className="analytics-performance-table"><thead><tr><th>Product</th><th>SKU</th><th>Views</th><th>Clicks</th><th>Enquiries</th><th>Conversion</th></tr></thead><tbody>{products.map((product) => <tr key={product.productId}><td>{product.productName}</td><td>{product.sku}</td><td>{product.views}</td><td>{product.clicks}</td><td>{product.enquiries}</td><td>{product.conversionRate === null ? '—' : `${product.conversionRate}%`}</td></tr>)}</tbody></table></div> : <div className="analytics-panel-empty">No product performance data is available for this range.</div>}</section> }